def verify(result):
    cand = result.get('correct', '') if isinstance(result, dict) else str(result)
    delta = result['vars']['delta']
    return delta < 0 and ('elíptica' in cand) and ('hiperbólica' not in cand) and ('parabólica' not in cand)

def verify(result):
    A = result['vars']['A']
    B = result['vars']['B']
    C = result['vars']['C']
    return int(result['correct']) == (B**2 - 4*A*C)

def verify(result):
    v = result['vars']
    return v['delta'] > 0 and len([o for o in result['options'] if o['is_correct']]) >= 2

def verify(result):
    cand = result.get('correct', '') if isinstance(result, dict) else str(result)
    delta = result['vars']['delta']
    return delta == 0 and ('parabólica' in cand or 'parabólico' in cand) and ('hiperbólica' not in cand) and ('hiperbólico' not in cand) and ('elíptica' not in cand)
